//! Actual World reach, no pickup effects, and interrupted approach.
use gielinor_cache::{game::GameCache,symbols};use gielinor_server::content::location_content_search;
use gielinor_world::{CoordGrid,locations::Location,loc_collision,stats::Stats,npc::RandomSource,simulation::{World,PlayerData,Action,WorldEvent}};use std::path::Path;
struct NoRandom;impl RandomSource for NoRandom{fn below(&mut self,_:u32)->u32{panic!("Search drew RNG")}}
#[test]
fn seven_immediate_messages_seven_unreachable_and_seven_interrupted_approaches(){
 let root=std::env::var("PG_GAME_CACHE").unwrap();let names=std::env::var("PG_SYMBOLS").unwrap();let mut c=GameCache::open(Path::new(&root),0xff_ffff).unwrap();let defs=c.definitions_all().unwrap();let sym=|s|symbols::load(&[Path::new(&names)],s,None).unwrap();let handlers=location_content_search(&sym("loc"),&sym("content"),&sym("param"),&defs).unwrap();let mut cases=0;
 for id in[355,357,358,359,365,366,12963]{for mode in 0..3{let mut w=World::default();for x in(3208..=3232).step_by(8){for z in(3208..=3232).step_by(8){w.collision.allocate(x,z,0);}}w.location_handlers=handlers.clone();let collision=defs.locations[&id].collision;w.location_types.insert(id,collision);let coords=CoordGrid::new(3220,3220,0).unwrap();let loc=Location::new(coords,id,10,0).unwrap();w.locations.load(loc);loc_collision::toggle(&mut w.collision,coords,10,0,collision,true).unwrap();
 if mode==1{for dx in -1..=1{for dz in -1..=1{if dx==0&&dz==0{continue}let p=CoordGrid::new(3220+dx,3220+dz,0).unwrap();let l=Location::new(p,id,10,0).unwrap();w.locations.load(l);loc_collision::toggle(&mut w.collision,p,10,0,collision,true).unwrap();}}}
 let start=CoordGrid::new(if mode==1{3223}else{3220},if mode==0{3221}else{3224},0).unwrap();let mut stats=Stats::default();stats.set_base(3,99);stats.set_current(3,70);stats.set_fine_xp(3,130344311).unwrap();let data=PlayerData::new(1,"Independent Search reach".into(),start,stats);w.queue_login(1,data).unwrap();w.tick_with_random(&mut NoRandom).unwrap();let a=w.actors().next().unwrap();w.drain_events();let before=w.data(a).unwrap().clone();w.submit(a,Action::OperateLocation{coords,id,operation:1,control:false}).unwrap();w.tick_with_random(&mut NoRandom).unwrap();let mut events=w.drain_events();
 if mode==2{let moved=w.data(a).unwrap().coords;assert_ne!(moved,start,"approach must really move before replacement");assert!(!events.iter().any(|e|matches!(e,WorldEvent::LocationMessage{..})));w.submit(a,Action::Walk{destination:CoordGrid::new(3228,3224,0).unwrap(),run:false}).unwrap();}
 for _ in 0..16{w.tick_with_random(&mut NoRandom).unwrap();events.extend(w.drain_events());}
 let messages=events.iter().filter(|e|matches!(e,WorldEvent::LocationMessage{..})).count();assert_eq!(messages,usize::from(mode==0),"id={id} mode={mode}");if mode==1{assert!(events.iter().any(|e|matches!(e,WorldEvent::CannotReach(_))),"ring must produce authoritative cannot-reach");}
 assert!(!events.iter().any(|e|matches!(e,WorldEvent::PlayerAnimation{..}|WorldEvent::PlayerSound{..}|WorldEvent::DoorSound{..}|WorldEvent::AreaSound(_)|WorldEvent::GroundAction{..}|WorldEvent::Drop{..}|WorldEvent::CombatAnimation{..}|WorldEvent::PlayerSpotAnimation{..})),"invented pickup/animation/sound");let after=w.data(a).unwrap();assert_eq!(after.inventory,before.inventory);assert_eq!(after.stats,before.stats);assert_eq!(after.equipment,before.equipment);assert_eq!(w.locations.find_type(coords,id),Some(loc));println!("PG_SEARCH_REACH id={id} mode={mode} messages={messages} no_reward_animation_sound_RNG=true");cases+=1;
 }}assert_eq!(cases,21);
}
